'use strict';
globalThis.YCReels=(()=>{
 const icons={heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',save:'M6 3h12v18l-6-4-6 4Z',folder:'M3 6h7l2 2h9v12H3Z',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7'};
 const icon=name=>`<svg viewBox="0 0 24 24" width="21" height="21" aria-hidden="true"><path d="${icons[name]}"/></svg>`;
 function companyActions({company:c,liked,saved,escape:e,context='reels'}){
  const like=context==='reels'?'data-reel-action="like"':`data-like="${c.id}"`,save=context==='reels'?'data-reel-action="save"':'id="save-company"';
  let website='';try{const url=new URL(c.website);if(['http:','https:'].includes(url.protocol))website=url.href;}catch{}
  return `<div class="reel-actions"><button type="button" class="reel-icon-action" ${like} aria-pressed="${liked}" aria-label="${liked?'Unlike':'Like'} ${e(c.name)}">${icon('heart')}<span>Like</span></button><button type="button" class="reel-icon-action" ${save} aria-pressed="${saved}" aria-label="${saved?'Unsave':'Save'} ${e(c.name)}">${icon('save')}<span>Save</span></button><button type="button" class="reel-icon-action" data-company-menu="${c.id}" aria-haspopup="menu" aria-expanded="false" aria-label="${saved?'Move':'Save'} ${e(c.name)} to a folder">${icon('folder')}<span>Folder</span></button>${website?`<a class="reel-icon-action" href="${e(website)}" target="_blank" rel="noopener noreferrer">${icon('external')}<span>Visit</span></a>`:`<span class="reel-icon-action" aria-disabled="true" title="No website listed">${icon('external')}<span>Visit</span></span>`}</div>`;
 }
 class View{
  constructor({engine,store,library,root,escape,logo,changed}){Object.assign(this,{engine,store,library,root,escape,logo,changed});this.current=null;this.active=false;this.reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;this.paused=this.reduced;this.speed=100;this.lastWheel=0;
   root.addEventListener('click',event=>{const action=event.target.closest('[data-reel-action]')?.dataset.reelAction;if(action==='next')this.navigate('next');if(action==='previous')this.navigate('previous');if(action==='like'&&this.current){store.toggle(this.current.company.id);changed();}if(action==='save'&&this.current){const id=this.current.company.id;if(library.has(id))library.remove([id]);else library.save(id);changed();}if(action==='pause')this.setPaused(!this.paused);if(action==='restart')window.atlasDesktop?.controlReel({restart:true}).catch(()=>{});});
   root.addEventListener('change',event=>{if(event.target.id==='reel-speed'){this.speed=Number(event.target.value);window.atlasDesktop?.controlReel({speed:this.speed}).catch(()=>{});}});
   root.addEventListener('wheel',event=>{if(event.target.closest('.reel-side,.reel-footer')||Math.abs(event.deltaY)<20||event.ctrlKey)return;event.preventDefault();if(Date.now()-this.lastWheel>750){this.lastWheel=Date.now();this.navigate(event.deltaY>0?'next':'previous');}},{passive:false});
   document.addEventListener('keydown',event=>{if(!this.active||document.querySelector('dialog[open]')||!document.getElementById('library-menu').hidden||document.getElementById('reel-filter-panel')?.hidden===false||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||document.activeElement.isContentEditable||event.isComposing)return;if((event.code==='Space'||event.key===' ')&&!event.ctrlKey&&!event.metaKey&&!event.altKey&&!document.activeElement.closest('#reel-feed-controls')){event.preventDefault();if(!event.repeat&&this.current)this.setPaused(!this.paused);return;}if(['ArrowDown','PageDown','ArrowUp','PageUp'].includes(event.key)){event.preventDefault();this.navigate(['ArrowDown','PageDown'].includes(event.key)?'next':'previous');}});
   new ResizeObserver(()=>this.resize()).observe(root);window.addEventListener('resize',()=>this.resize());
  }
  setPaused(paused,sync=true){this.paused=Boolean(paused);if(sync)window.atlasDesktop?.controlReel({paused:this.paused}).catch(()=>{});const button=this.root.querySelector('[data-reel-action="pause"]');if(button){button.textContent=this.paused?'Resume scroll':'Pause scroll';button.setAttribute('aria-pressed',String(this.paused));}}
  enter(){this.active=true;if(!this.current)this.current=this.engine.next();this.render();}
  leave(){if(this.active){this.active=false;window.atlasDesktop?.hideReel().catch(()=>{});}}
  navigate(direction){if(this.moving)return;const next=direction==='previous'?this.engine.previous():this.engine.next();if(next){this.current=next;if(!this.reduced){this.moving=true;setTimeout(()=>{this.moving=false;},360);}this.render(direction);}}
  bounds(){const r=document.getElementById('reel-website')?.getBoundingClientRect();return r?{x:r.x,y:r.y,width:r.width,height:r.height}:null;}
  resize(){if(this.active&&this.current&&window.atlasDesktop){const bounds=this.bounds();if(bounds)window.atlasDesktop.resizeReel(bounds).catch(()=>{});}}
  render(direction=null){if(!this.active)return;const item=this.current;if(!item){window.atlasDesktop?.hideReel().catch(()=>{});this.root.innerHTML=`<div class="reel-empty"><h2>No matching companies</h2><p>${this.scopeFiltered?'No companies with websites match these filters.':'There are no companies with websites in this snapshot.'}</p>${this.scopeFiltered?'<button type="button" class="quiet-button" data-clear-reel-filters>Back to For you</button>':''}</div>`;return;}const c=item.company,e=this.escape;
   if(this.lastCompanyId!==undefined&&this.lastCompanyId!==c.id)this.paused=false;this.lastCompanyId=c.id;
   this.root.innerHTML=`<div class="reel-layout"><div id="reel-website" class="reel-website"><div class="reel-load-message" role="status"><strong>${e(c.name)}</strong><span id="reel-status">${window.atlasDesktop?'Opening live website…':'Live website reels are available in the desktop app.'}</span><a href="${e(c.website)}" target="_blank" rel="noopener noreferrer">Open website</a></div></div><aside class="reel-side"><div class="reel-company-logo">${this.logo(c)}</div><h2>${e(c.name)}</h2><p class="reel-summary">${e(c.summary)}</p><p class="reel-meta">${e(c.batch)} / ${e(c.status)}</p><p class="reel-meta">${e(c.location)}</p>${companyActions({company:c,liked:this.store.likes.has(c.id),saved:this.library.has(c.id),escape:e})}<p class="reel-reason">${e(item.reason)}</p><div class="tags">${c.tags.map(tag=>`<span class="tag">${e(tag)}</span>`).join('')}</div><details class="reel-description" open><summary>Company description</summary><p>${e(c.description||c.summary)}</p></details><a class="reel-yc-link" href="https://www.ycombinator.com/companies/${encodeURIComponent(c.slug)}" target="_blank" rel="noopener noreferrer">YC profile ↗</a></aside></div>
   <div class="reel-footer"><div class="reel-context"><a class="reel-domain" href="${e(c.website)}" target="_blank" rel="noopener noreferrer" title="${e(c.website)}">${e(c.website.replace(/^https?:\/\//,'').replace(/^www\./,'').split(/[/?#]/)[0])}</a></div><div class="reel-playback"><button type="button" data-reel-action="pause" aria-keyshortcuts="Space" aria-pressed="${this.paused}" title="Pause or resume scrolling (Space)">${this.paused?'Resume scroll':'Pause scroll'}</button><label>Speed <select id="reel-speed">${[60,100,150,220].map(speed=>`<option value="${speed}" ${speed===this.speed?'selected':''}>${speed} px/s</option>`).join('')}</select></label><button type="button" data-reel-action="restart">Restart</button></div><div class="reel-navigation"><button type="button" data-reel-action="previous" ${this.engine.index<1?'disabled':''}>Previous</button><button type="button" data-reel-action="next" ${this.engine.peekNext()?'':'disabled'}>Next</button></div></div>`;
   if(direction&&!this.reduced){const panel=this.root.querySelector(window.atlasDesktop?'.reel-side':'.reel-layout');panel?.animate?.([{transform:`translateY(${direction==='previous'?'-':''}64px)`,opacity:.25},{transform:'translateY(0)',opacity:1}],{duration:360,easing:'cubic-bezier(.22,.7,.25,1)'});}
   if(window.atlasDesktop){requestAnimationFrame(()=>{if(!this.active||this.current?.company.id!==c.id)return;window.atlasDesktop.controlReel({paused:this.paused,speed:this.speed}).catch(()=>{});window.atlasDesktop.showReel({companyId:c.id,bounds:this.bounds(),animate:Boolean(direction)&&!this.reduced,direction:direction||'next'}).then(()=>{if(this.active&&this.current?.company.id===c.id){const next=this.engine.peekNext();if(next)window.atlasDesktop.preloadReels([next.company.id]).catch(()=>{});}}).catch(error=>this.status({companyId:c.id,state:'failed',message:error.message}));});}
  }
  transition(event){
   const finish=()=>window.atlasDesktop?.finishReelTransition({companyId:event.companyId,transitionId:event.transitionId}).catch(()=>{});
   if(!this.active||event.companyId!==this.current?.company.id||this.reduced){finish();return;}
   const viewport=document.getElementById('reel-website');if(!viewport||typeof viewport.animate!=='function'){finish();return;}
   const layer=document.createElement('div');layer.className='reel-transition';layer.setAttribute('aria-hidden','true');
   const oldFrame=document.createElement('img'),newFrame=document.createElement('img');oldFrame.src=event.from;newFrame.src=event.to;oldFrame.alt='';newFrame.alt='';layer.append(oldFrame,newFrame);viewport.append(layer);
   const sign=event.direction==='previous'?-1:1,options={duration:event.duration,easing:'cubic-bezier(.22,.7,.25,1)',fill:'forwards'};
   const animations=[oldFrame.animate([{transform:'translateY(0)'},{transform:`translateY(${-sign*100}%)`}],options),newFrame.animate([{transform:`translateY(${sign*100}%)`},{transform:'translateY(0)'}],options)];
   Promise.all(animations.map(animation=>animation.finished)).catch(()=>{}).finally(()=>{layer.remove();finish();});
  }
  status(event){if(this.active&&event.companyId===this.current?.company.id){const status=document.getElementById('reel-status');if(status)status.textContent=event.message;this.root.dataset.state=event.state;}}
 }
 return Object.freeze({View,companyActions});
})();
